TEXT_FILES['frontend/src/pages/Login.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, Navigate, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { ApiError } from "../api/client";\n\nexport default function Login() {\n  const { login, user } = useAuth();\n  const navigate = useNavigate();\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  if (user) return <Navigate to="/aujourdhui" replace />;\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      await login(email, password);\n      navigate("/aujourdhui");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Connexion impossible, reessaie.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Connexion</h1>\n          <p className="text-muted text-sm mb-6">Reprends ton entrainement la ou tu l\'as laisse.</p>\n\n          <form onSubmit={onSubmit} className="space-y-4">\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="email">\n                Email\n              </label>\n              <input\n                id="email"\n                type="email"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="password">\n                Mot de passe\n              </label>\n              <input\n                id="password"\n                type="password"\n                required\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n\n            {error && <p className="text-sm text-accent">{error}</p>}\n\n            <button\n              type="submit"\n              disabled={busy}\n              className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n            >\n              {busy ? "Connexion..." : "Se connecter"}\n            </button>\n          </form>\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          Pas encore de compte ?{" "}\n          <Link to="/inscription" className="text-accent hover:text-accentSoft">\n            Cree-en un\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
TEXT_FILES['frontend/src/pages/Register.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, Navigate, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { ApiError } from "../api/client";\n\nexport default function Register() {\n  const { register, user } = useAuth();\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  if (user) return <Navigate to="/aujourdhui" replace />;\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      await register(email, password, name);\n      navigate("/profil");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Inscription impossible, reessaie.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Creer un compte</h1>\n          <p className="text-muted text-sm mb-6">Rejoins ou cree ton premier camp d\'entrainement.</p>\n\n          <form onSubmit={onSubmit} className="space-y-4">\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="name">\n                Prenom\n              </label>\n              <input\n                id="name"\n                required\n                value={name}\n                onChange={(e) => setName(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="email">\n                Email\n              </label>\n              <input\n                id="email"\n                type="email"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="password">\n                Mot de passe\n              </label>\n              <input\n                id="password"\n                type="password"\n                required\n                minLength={8}\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n              <p className="text-xs text-muted mt-1">8 caracteres minimum.</p>\n            </div>\n\n            {error && <p className="text-sm text-accent">{error}</p>}\n\n            <button\n              type="submit"\n              disabled={busy}\n              className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n            >\n              {busy ? "Creation..." : "Creer mon compte"}\n            </button>\n          </form>\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          Deja un compte ?{" "}\n          <Link to="/connexion" className="text-accent hover:text-accentSoft">\n            Connecte-toi\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
TEXT_FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst navItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/chrono", label: "Chrono" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/profil", label: "Profil" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-6">\n          <div className="flex items-center gap-2 mb-8">\n            <img src="/logo-mark.png" alt="" className="w-8 h-8 object-contain" />\n            <span className="font-display text-lg tracking-wide uppercase">GoTeam</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {navItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se deconnecter\n          </button>\n        </div>\n      </header>\n\n      <nav className="md:hidden flex justify-around bg-surface border-b border-border order-2">\n        {navItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 text-center py-3 text-xs font-medium ${isActive ? "text-accent" : "text-muted"}`\n            }\n          >\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n\n      <main className="flex-1 p-5 md:p-10 max-w-4xl mx-auto w-full">{children}</main>\n    </div>\n  );\n}\n'
TEXT_FILES['frontend/index.html'] = '<!doctype html>\n<html lang="fr">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <meta name="theme-color" content="#1B8CA3" />\n    <title>GoTeam</title>\n    <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png" />\n    <link rel="icon" type="image/png" sizes="64x64" href="/favicon-64.png" />\n    <link rel="apple-touch-icon" href="/icon-192.png" />\n    <link rel="preconnect" href="https://fonts.googleapis.com" />\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n    <link\n      href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap"\n      rel="stylesheet"\n    />\n    <link rel="manifest" href="/manifest.json" />\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.tsx"></script>\n  </body>\n</html>\n'
TEXT_FILES['frontend/public/manifest.json'] = '{\n  "name": "GoTeam",\n  "short_name": "GoTeam",\n  "start_url": "/",\n  "display": "standalone",\n  "background_color": "#F2FAFB",\n  "theme_color": "#1B8CA3",\n  "icons": [\n    { "src": "/icon-192.png", "sizes": "192x192", "type": "image/png" },\n    { "src": "/icon-512.png", "sizes": "512x512", "type": "image/png" }\n  ]\n}\n'
TEXT_FILES['backend/src/routes/camps.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { generateCampCode } from "../utils/code";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst createCampSchema = z.object({\n  name: z.string().min(1, "Le nom du camp est requis."),\n  description: z.string().max(500).optional().nullable(),\n  exerciseIds: z.array(z.string()).min(1, "Selectionne au moins un exercice."),\n  startDate: z.string().optional().nullable(), // format ISO "YYYY-MM-DD"\n  endDate: z.string().optional().nullable(),\n});\n\n// Cree un camp : choix d\'un ensemble d\'exercices, generation d\'un code d\'invitation.\n// Le createur devient automatiquement membre du camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { name, description, exerciseIds, startDate, endDate } = parsed.data;\n\n  if (startDate && endDate && new Date(endDate) < new Date(startDate)) {\n    return res.status(400).json({ error: "La date de fin doit etre apres la date de debut." });\n  }\n\n  // On genere un code unique (tres faible probabilite de collision, on retente si besoin)\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const camp = await prisma.camp.create({\n    data: {\n      name,\n      description: description || null,\n      code,\n      createdById: req.userId!,\n      startDate: startDate ? new Date(startDate) : null,\n      endDate: endDate ? new Date(endDate) : null,\n      exercises: { create: exerciseIds.map((exerciseId) => ({ exerciseId })) },\n      members: { create: [{ userId: req.userId! }] },\n    },\n    include: { exercises: { include: { exercise: true } }, members: true },\n  });\n\n  res.status(201).json(camp);\n});\n\nconst joinSchema = z.object({ code: z.string().min(1) });\n\n// Rejoint un camp existant via son code d\'invitation\nrouter.post("/join", async (req: AuthRequest, res) => {\n  const parsed = joinSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Code requis." });\n  }\n  const code = parsed.data.code.trim().toUpperCase();\n\n  const camp = await prisma.camp.findUnique({ where: { code } });\n  if (!camp) {\n    return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n  }\n\n  const existing = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: camp.id } },\n  });\n  if (existing) {\n    return res.status(200).json({ message: "Tu es deja membre de ce camp.", campId: camp.id });\n  }\n\n  await prisma.campMembership.create({ data: { userId: req.userId!, campId: camp.id } });\n  res.status(201).json({ message: `Bienvenue dans le camp "${camp.name}" !`, campId: camp.id });\n});\n\n// Liste les camps dont l\'utilisateur est membre\nrouter.get("/mine", async (req: AuthRequest, res) => {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: {\n          exercises: { include: { exercise: true } },\n          _count: { select: { members: true } },\n        },\n      },\n    },\n    orderBy: { joinedAt: "desc" },\n  });\n  res.json(memberships.map((m) => m.camp));\n});\n\n// Detail d\'un camp (verifie que l\'utilisateur en est bien membre)\nrouter.get("/:id", async (req: AuthRequest, res) => {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: req.params.id } },\n  });\n  if (!membership) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: {\n      exercises: { include: { exercise: true } },\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  res.json(camp);\n});\n\nconst updateCampSchema = z.object({\n  name: z.string().min(1).optional(),\n  description: z.string().max(500).optional().nullable(),\n});\n\n// Modifie le nom/descriptif d\'un camp : reserve au createur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le modifier." });\n  }\n\n  const parsed = updateCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n\n  const updated = await prisma.camp.update({\n    where: { id: req.params.id },\n    data: parsed.data,\n  });\n  res.json(updated);\n});\n\n// Supprime definitivement un camp : reserve au createur du camp.\n// Supprime aussi en cascade les exercices du camp, les adhesions, les logs et les messages associes.\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le supprimer." });\n  }\n\n  await prisma.camp.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\n// Classement des membres du camp base UNIQUEMENT sur leur regularite personnelle\n// (taux de seances realisees par rapport aux seances dues, et jours consecutifs) --\n// jamais sur les performances (poids, repetitions, etc.).\nrouter.get("/:id/leaderboard", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: campId },\n    include: {\n      exercises: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const today = toDayStart(new Date());\n  const results = [];\n\n  for (const member of camp.members) {\n    const logs = await prisma.exerciseLog.findMany({\n      where: { userId: member.userId, campId },\n      select: { date: true },\n    });\n    const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n\n    let dueCount = 0;\n    let doneCount = 0;\n    for (const ce of camp.exercises) {\n      const effectiveStart = toDayStart(\n        new Date(Math.max(new Date(ce.startDate).getTime(), new Date(member.joinedAt).getTime()))\n      );\n      const cursor = new Date(effectiveStart);\n      while (cursor.getTime() <= today.getTime()) {\n        if (isDueOnDate(ce, cursor)) {\n          dueCount++;\n          if (completedDates.has(cursor.toISOString().slice(0, 10))) doneCount++;\n        }\n        cursor.setUTCDate(cursor.getUTCDate() + 1);\n      }\n    }\n    const regularityRate = dueCount > 0 ? Math.round((doneCount / dueCount) * 100) : 0;\n\n    // Streak propre a ce camp : jours consecutifs (en remontant depuis aujourd\'hui/hier)\n    // avec au moins une seance validee dans ce camp.\n    let streak = 0;\n    const cursor2 = toDayStart(today);\n    if (!completedDates.has(cursor2.toISOString().slice(0, 10))) {\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n    for (let i = 0; i < 3650; i++) {\n      const key = cursor2.toISOString().slice(0, 10);\n      if (!completedDates.has(key)) break;\n      streak++;\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n\n    results.push({\n      userId: member.userId,\n      name: member.user.name,\n      regularityRate,\n      streak,\n      dueCount,\n      doneCount,\n    });\n  }\n\n  results.sort((a, b) => b.regularityRate - a.regularityRate || b.streak - a.streak);\n  res.json(results);\n});\n\nexport default router;\n'
TEXT_FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useNavigate, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface CampExerciseData extends Program {\n  exercise: { id: string; name: string; unit: "REPS" | "SECONDS"; description: string | null };\n}\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  description: string | null;\n  code: string;\n  createdById: string;\n  startDate: string | null;\n  endDate: string | null;\n  exercises: CampExerciseData[];\n  members: { user: { id: string; name: string } }[];\n}\n\nconst RECURRENCE_LABEL: Record<string, (p: Program) => string> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n};\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const navigate = useNavigate();\n  const { user } = useAuth();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n  const [editingDescription, setEditingDescription] = useState(false);\n  const [descriptionDraft, setDescriptionDraft] = useState("");\n  const [savingDescription, setSavingDescription] = useState(false);\n  const [confirmingDelete, setConfirmingDelete] = useState(false);\n  const [deleting, setDeleting] = useState(false);\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n  }\n  useEffect(load, [id]);\n\n  async function deleteCamp() {\n    if (!camp) return;\n    setDeleting(true);\n    try {\n      await api.del(`/camps/${camp.id}`);\n      navigate("/camps");\n    } finally {\n      setDeleting(false);\n    }\n  }\n\n  async function saveDescription() {\n    if (!camp) return;\n    setSavingDescription(true);\n    try {\n      await api.put(`/camps/${camp.id}`, { description: descriptionDraft.trim() || null });\n      setEditingDescription(false);\n      load();\n    } finally {\n      setSavingDescription(false);\n    }\n  }\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const isCoach = user?.id === camp.createdById;\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent">{camp.code}</p>\n        </div>\n      </div>\n\n      <div className="flex items-center gap-4 flex-wrap mt-2">\n        <Link to={`/camps/${camp.id}/discussion`} className="text-sm text-accent hover:text-accentSoft">\n          💬 Discussion du camp\n        </Link>\n        <Link to={`/camps/${camp.id}/classement`} className="text-sm text-accent hover:text-accentSoft">\n          📊 Classement (regularite)\n        </Link>\n        {isCoach && (\n          <button\n            onClick={() => setConfirmingDelete(true)}\n            className="text-sm text-muted hover:text-accent ml-auto"\n          >\n            Supprimer le camp\n          </button>\n        )}\n      </div>\n\n      {confirmingDelete && (\n        <div className="bg-surface border border-accent rounded-lg p-4 mt-3">\n          <p className="text-sm mb-3">\n            Supprimer definitivement le camp "{camp.name}" ? Cette action est irreversible : l\'historique des\n            seances de tous les membres pour ce camp sera perdu.\n          </p>\n          <div className="flex gap-2">\n            <button\n              onClick={deleteCamp}\n              disabled={deleting}\n              className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n            >\n              {deleting ? "Suppression..." : "Oui, supprimer"}\n            </button>\n            <button\n              onClick={() => setConfirmingDelete(false)}\n              className="text-muted hover:text-text text-sm px-2"\n            >\n              Annuler\n            </button>\n          </div>\n        </div>\n      )}\n\n      <div className="mt-4">\n        {editingDescription ? (\n          <div className="bg-surface2 border border-border rounded-lg p-3">\n            <textarea\n              value={descriptionDraft}\n              onChange={(e) => setDescriptionDraft(e.target.value)}\n              placeholder="Descriptif du camp..."\n              rows={3}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none mb-2"\n            />\n            <div className="flex gap-2">\n              <button\n                onClick={saveDescription}\n                disabled={savingDescription}\n                className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n              >\n                {savingDescription ? "Enregistrement..." : "Enregistrer"}\n              </button>\n              <button\n                onClick={() => setEditingDescription(false)}\n                className="text-muted hover:text-text text-sm px-2"\n              >\n                Annuler\n              </button>\n            </div>\n          </div>\n        ) : camp.description ? (\n          <div className="flex items-start justify-between gap-3">\n            <p className="text-sm text-muted italic">{camp.description}</p>\n            {isCoach && (\n              <button\n                onClick={() => {\n                  setDescriptionDraft(camp.description ?? "");\n                  setEditingDescription(true);\n                }}\n                className="text-xs text-accent hover:text-accentSoft shrink-0"\n              >\n                Modifier\n              </button>\n            )}\n          </div>\n        ) : (\n          isCoach && (\n            <button\n              onClick={() => {\n                setDescriptionDraft("");\n                setEditingDescription(true);\n              }}\n              className="text-xs text-accent hover:text-accentSoft"\n            >\n              + Ajouter un descriptif au camp\n            </button>\n          )\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Exercices du camp</h2>\n      <p className="text-muted text-sm mb-4">\n        {isCoach\n          ? "En tant que createur du camp, tu definis la consigne (objectif, frequence) suivie par tous les membres."\n          : "Consignes definies par le createur du camp."}\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map((ce) => {\n          const isEditing = editingExerciseId === ce.exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={ce.exercise.id}\n                campId={camp.id}\n                exerciseId={ce.exercise.id}\n                exerciseName={ce.exercise.name}\n                unit={ce.exercise.unit}\n                existing={ce}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          const unitLabel = ce.exercise.unit === "REPS" ? "reps" : "";\n          const valueLabel =\n            ce.exercise.unit === "SECONDS" && ce.targetValue != null\n              ? secondsToMMSS(ce.targetValue)\n              : `${ce.targetValue} ${unitLabel}`;\n\n          return (\n            <div key={ce.exercise.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">{ce.exercise.name}</p>\n                  <p className="text-sm text-muted">\n                    {ce.targetMode === "MAX"\n                      ? `${ce.targetSets} serie${ce.targetSets > 1 ? "s" : ""} a fond`\n                      : `${ce.targetSets} x ${valueLabel}`}{" "}\n                    · {RECURRENCE_LABEL[ce.recurrenceType](ce)}\n                  </p>\n                  {ce.description && <p className="text-xs text-muted mt-1 italic">"{ce.description}"</p>}\n                </div>\n                <div className="flex gap-3 items-center shrink-0">\n                  <Link\n                    to={`/camps/${camp.id}/progression/${ce.exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                  {isCoach && (\n                    <button\n                      onClick={() => setEditingExerciseId(ce.exercise.id)}\n                      className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                    >\n                      Modifier\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
TEXT_FILES['frontend/src/pages/CampLeaderboard.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface LeaderboardEntry {\n  userId: string;\n  name: string;\n  regularityRate: number;\n  streak: number;\n  dueCount: number;\n  doneCount: number;\n}\n\nexport default function CampLeaderboard() {\n  const { id: campId } = useParams<{ id: string }>();\n  const [entries, setEntries] = useState<LeaderboardEntry[] | null>(null);\n  const [campName, setCampName] = useState("");\n\n  useEffect(() => {\n    if (!campId) return;\n    api.get<{ name: string }>(`/camps/${campId}`).then((c) => setCampName(c.name));\n    api.get<LeaderboardEntry[]>(`/camps/${campId}/leaderboard`).then(setEntries);\n  }, [campId]);\n\n  return (\n    <div className="max-w-xl">\n      <Link to={`/camps/${campId}`} className="text-sm text-muted hover:text-accent">\n        ← Retour au camp\n      </Link>\n      <h1 className="font-display text-3xl uppercase tracking-wide mt-2 mb-1">Classement · {campName}</h1>\n      <p className="text-muted text-sm mb-6">\n        Base uniquement sur la regularite (taux de seances realisees et jours consecutifs) — jamais sur la\n        performance. L\'idee est de s\'encourager, pas de se comparer sur qui fait le plus de repetitions.\n      </p>\n\n      {entries === null && <p className="text-muted">Chargement...</p>}\n\n      <div className="space-y-2">\n        {entries?.map((entry, index) => (\n          <div\n            key={entry.userId}\n            className="bg-surface border border-border rounded-lg p-4 flex items-center gap-4"\n          >\n            <div className="w-8 h-8 rounded-full bg-surface2 border border-border flex items-center justify-center font-display text-sm shrink-0">\n              {index + 1}\n            </div>\n            <div className="flex-1">\n              <p className="font-medium">{entry.name}</p>\n              <p className="text-xs text-muted">\n                {entry.doneCount} / {entry.dueCount} seances realisees\n              </p>\n            </div>\n            <div className="text-right shrink-0">\n              <p className="font-display text-xl text-accent">{entry.regularityRate}%</p>\n              <p className="text-[10px] uppercase tracking-wide text-muted">\n                {entry.streak} jour{entry.streak > 1 ? "s" : ""} d\'affilee\n              </p>\n            </div>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'
TEXT_FILES['frontend/src/pages/Chrono.tsx'] = 'import { useEffect, useMemo, useRef, useState } from "react";\nimport { api } from "../api/client";\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n  unit: "REPS" | "SECONDS";\n}\n\ninterface CircuitItem {\n  key: string; // cle unique locale (permet de mettre le meme exercice plusieurs fois si besoin)\n  name: string;\n}\n\ntype Phase =\n  | { type: "work"; exerciseName: string; duration: number; round: number; totalRounds: number; index: number; total: number }\n  | { type: "rest"; duration: number; round: number; totalRounds: number; nextExerciseName: string }\n  | { type: "roundRest"; duration: number; round: number; totalRounds: number };\n\n// Joue un petit bip via l\'API Web Audio (aucun fichier son necessaire)\nfunction beep(freq: number, duration = 180) {\n  try {\n    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;\n    const ctx = new AudioCtx();\n    const osc = ctx.createOscillator();\n    const gain = ctx.createGain();\n    osc.frequency.value = freq;\n    osc.connect(gain);\n    gain.connect(ctx.destination);\n    gain.gain.setValueAtTime(0.2, ctx.currentTime);\n    osc.start();\n    osc.stop(ctx.currentTime + duration / 1000);\n    osc.onended = () => ctx.close();\n  } catch {\n    // navigateur sans Web Audio : tant pis, pas de son\n  }\n}\n\nfunction buildPhases(items: CircuitItem[], workSeconds: number, restSeconds: number, rounds: number, roundRestSeconds: number): Phase[] {\n  const phases: Phase[] = [];\n  for (let round = 1; round <= rounds; round++) {\n    items.forEach((item, index) => {\n      phases.push({\n        type: "work",\n        exerciseName: item.name,\n        duration: workSeconds,\n        round,\n        totalRounds: rounds,\n        index: index + 1,\n        total: items.length,\n      });\n      const isLastExerciseOfRound = index === items.length - 1;\n      if (!isLastExerciseOfRound && restSeconds > 0) {\n        phases.push({\n          type: "rest",\n          duration: restSeconds,\n          round,\n          totalRounds: rounds,\n          nextExerciseName: items[index + 1].name,\n        });\n      }\n    });\n    if (round < rounds && roundRestSeconds > 0) {\n      phases.push({ type: "roundRest", duration: roundRestSeconds, round, totalRounds: rounds });\n    }\n  }\n  return phases;\n}\n\nexport default function Chrono() {\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [search, setSearch] = useState("");\n  const [items, setItems] = useState<CircuitItem[]>([]);\n  const [customName, setCustomName] = useState("");\n\n  const [workSeconds, setWorkSeconds] = useState(40);\n  const [restSeconds, setRestSeconds] = useState(20);\n  const [rounds, setRounds] = useState(3);\n  const [roundRestSeconds, setRoundRestSeconds] = useState(60);\n\n  const [phases, setPhases] = useState<Phase[] | null>(null);\n  const [phaseIndex, setPhaseIndex] = useState(0);\n  const [remaining, setRemaining] = useState(0);\n  const [running, setRunning] = useState(false);\n  const [finished, setFinished] = useState(false);\n  const intervalRef = useRef<number | null>(null);\n\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n  }, []);\n\n  const filteredCatalog = useMemo(\n    () => catalog.filter((e) => e.name.toLowerCase().includes(search.toLowerCase())),\n    [catalog, search]\n  );\n\n  function addItem(name: string) {\n    setItems((prev) => [...prev, { key: `${name}-${Date.now()}-${Math.random()}`, name }]);\n  }\n\n  async function addCustom() {\n    if (!customName.trim()) return;\n    try {\n      const created = await api.post<CatalogExercise>("/exercises", { name: customName.trim(), unit: "REPS" });\n      setCatalog((prev) => [...prev, created]);\n      addItem(created.name);\n    } catch {\n      // si la creation echoue (ex: hors ligne), on ajoute quand meme localement au circuit\n      addItem(customName.trim());\n    }\n    setCustomName("");\n  }\n\n  function removeItem(key: string) {\n    setItems((prev) => prev.filter((i) => i.key !== key));\n  }\n\n  function moveItem(key: string, direction: -1 | 1) {\n    setItems((prev) => {\n      const index = prev.findIndex((i) => i.key === key);\n      const newIndex = index + direction;\n      if (newIndex < 0 || newIndex >= prev.length) return prev;\n      const copy = [...prev];\n      [copy[index], copy[newIndex]] = [copy[newIndex], copy[index]];\n      return copy;\n    });\n  }\n\n  function startCircuit() {\n    if (items.length === 0) return;\n    const built = buildPhases(items, workSeconds, restSeconds, rounds, roundRestSeconds);\n    setPhases(built);\n    setPhaseIndex(0);\n    setRemaining(built[0].duration);\n    setFinished(false);\n    setRunning(true);\n    beep(880);\n  }\n\n  function stopCircuit() {\n    setPhases(null);\n    setRunning(false);\n    setFinished(false);\n    if (intervalRef.current) window.clearInterval(intervalRef.current);\n  }\n\n  function skipPhase() {\n    if (!phases) return;\n    if (phaseIndex + 1 >= phases.length) {\n      setFinished(true);\n      setRunning(false);\n      beep(660, 400);\n      return;\n    }\n    setPhaseIndex((i) => i + 1);\n    setRemaining(phases[phaseIndex + 1].duration);\n    beep(phases[phaseIndex + 1].type === "work" ? 880 : 440);\n  }\n\n  useEffect(() => {\n    if (!running || !phases) return;\n    intervalRef.current = window.setInterval(() => {\n      setRemaining((r) => {\n        if (r <= 1) {\n          // passage a la phase suivante (ou fin du circuit)\n          if (phaseIndex + 1 >= phases.length) {\n            setFinished(true);\n            setRunning(false);\n            beep(660, 400);\n            return 0;\n          }\n          setPhaseIndex((i) => i + 1);\n          beep(phases[phaseIndex + 1].type === "work" ? 880 : 440);\n          return phases[phaseIndex + 1].duration;\n        }\n        return r - 1;\n      });\n    }, 1000);\n    return () => {\n      if (intervalRef.current) window.clearInterval(intervalRef.current);\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [running, phases, phaseIndex]);\n\n  const currentPhase = phases ? phases[phaseIndex] : null;\n\n  // --- Ecran "circuit en cours" ---\n  if (phases && currentPhase) {\n    const phaseColor =\n      currentPhase.type === "work" ? "text-accent border-accent" : "text-success border-success";\n\n    return (\n      <div className="max-w-md mx-auto text-center pt-6">\n        {finished ? (\n          <>\n            <h1 className="font-display text-3xl uppercase tracking-wide mb-4">Circuit termine ! 🎉</h1>\n            <p className="text-muted text-sm mb-6">Bien joue, seance complete.</p>\n            <button\n              onClick={stopCircuit}\n              className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2"\n            >\n              Retour\n            </button>\n          </>\n        ) : (\n          <>\n            <p className="text-muted text-sm mb-1">\n              Tour {currentPhase.round} / {currentPhase.totalRounds}\n              {currentPhase.type === "work" && ` · Exercice ${currentPhase.index}/${currentPhase.total}`}\n            </p>\n            <div className={`border-4 rounded-full w-56 h-56 mx-auto flex flex-col items-center justify-center my-6 ${phaseColor}`}>\n              <p className="font-display text-6xl">{remaining}</p>\n              <p className="text-xs text-muted uppercase tracking-wide">secondes</p>\n            </div>\n            <h2 className="font-display text-2xl uppercase tracking-wide mb-1">\n              {currentPhase.type === "work"\n                ? currentPhase.exerciseName\n                : currentPhase.type === "rest"\n                ? `Repos — ensuite : ${currentPhase.nextExerciseName}`\n                : "Repos entre les tours"}\n            </h2>\n\n            <div className="flex justify-center gap-3 mt-6">\n              <button\n                onClick={() => setRunning((r) => !r)}\n                className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n              >\n                {running ? "Pause" : "Reprendre"}\n              </button>\n              <button\n                onClick={skipPhase}\n                className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n              >\n                Passer\n              </button>\n              <button onClick={stopCircuit} className="text-muted hover:text-accent text-sm px-3 py-2">\n                Arreter\n              </button>\n            </div>\n          </>\n        )}\n      </div>\n    );\n  }\n\n  // --- Ecran de construction du circuit ---\n  return (\n    <div className="max-w-2xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Chronometre</h1>\n      <p className="text-muted text-sm mb-6">\n        Construis ta propre seance en circuit training : choisis tes exercices, le temps de travail et de repos,\n        le nombre de tours, et lance le chrono.\n      </p>\n\n      <div className="grid md:grid-cols-2 gap-6">\n        <div>\n          <h2 className="font-display uppercase tracking-wide text-sm mb-2">1. Choisis tes exercices</h2>\n          <input\n            placeholder="Rechercher un exercice..."\n            value={search}\n            onChange={(e) => setSearch(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-2 text-sm"\n          />\n          <div className="grid grid-cols-2 gap-1.5 max-h-40 overflow-y-auto mb-2">\n            {filteredCatalog.map((exo) => (\n              <button\n                key={exo.id}\n                type="button"\n                onClick={() => addItem(exo.name)}\n                className="text-left text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-2 py-1.5"\n              >\n                + {exo.name}\n              </button>\n            ))}\n          </div>\n          <div className="flex gap-2">\n            <input\n              value={customName}\n              onChange={(e) => setCustomName(e.target.value)}\n              placeholder="Nouvel exercice..."\n              className="flex-1 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n            />\n            <button\n              type="button"\n              onClick={addCustom}\n              className="bg-accent text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n            >\n              Ajouter\n            </button>\n          </div>\n\n          <h3 className="font-display uppercase tracking-wide text-xs mt-4 mb-2 text-muted">\n            Circuit ({items.length} exercice{items.length > 1 ? "s" : ""})\n          </h3>\n          <div className="space-y-1.5">\n            {items.length === 0 && <p className="text-muted text-sm italic">Aucun exercice ajoute pour l\'instant.</p>}\n            {items.map((item, index) => (\n              <div\n                key={item.key}\n                className="flex items-center justify-between bg-surface border border-border rounded-md px-3 py-1.5 text-sm"\n              >\n                <span>\n                  {index + 1}. {item.name}\n                </span>\n                <div className="flex gap-1 items-center">\n                  <button onClick={() => moveItem(item.key, -1)} className="text-muted hover:text-text px-1">\n                    ↑\n                  </button>\n                  <button onClick={() => moveItem(item.key, 1)} className="text-muted hover:text-text px-1">\n                    ↓\n                  </button>\n                  <button onClick={() => removeItem(item.key)} className="text-muted hover:text-accent px-1">\n                    ✕\n                  </button>\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n\n        <div>\n          <h2 className="font-display uppercase tracking-wide text-sm mb-2">2. Reglages du circuit</h2>\n          <div className="bg-surface border border-border rounded-lg p-4 space-y-3">\n            <div>\n              <label className="block text-xs text-muted mb-1">Temps de travail (secondes)</label>\n              <input\n                type="number"\n                min={5}\n                value={workSeconds}\n                onChange={(e) => setWorkSeconds(Number(e.target.value))}\n                className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n            </div>\n            <div>\n              <label className="block text-xs text-muted mb-1">Temps de repos entre exercices (secondes)</label>\n              <input\n                type="number"\n                min={0}\n                value={restSeconds}\n                onChange={(e) => setRestSeconds(Number(e.target.value))}\n                className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n            </div>\n            <div>\n              <label className="block text-xs text-muted mb-1">Nombre de tours</label>\n              <input\n                type="number"\n                min={1}\n                value={rounds}\n                onChange={(e) => setRounds(Number(e.target.value))}\n                className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n            </div>\n            <div>\n              <label className="block text-xs text-muted mb-1">Repos entre chaque tour (secondes)</label>\n              <input\n                type="number"\n                min={0}\n                value={roundRestSeconds}\n                onChange={(e) => setRoundRestSeconds(Number(e.target.value))}\n                className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n            </div>\n          </div>\n\n          <button\n            onClick={startCircuit}\n            disabled={items.length === 0}\n            className="w-full mt-4 bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2.5 disabled:opacity-50"\n          >\n            Lancer le circuit\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n'
TEXT_FILES['frontend/src/App.tsx'] = 'import { Navigate, Route, Routes } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "./context/AuthContext";\nimport Layout from "./components/Layout";\n\nimport Login from "./pages/Login";\nimport Register from "./pages/Register";\nimport Profile from "./pages/Profile";\nimport Dashboard from "./pages/Dashboard";\nimport CreateCamp from "./pages/CreateCamp";\nimport JoinCamp from "./pages/JoinCamp";\nimport CampDetail from "./pages/CampDetail";\nimport Today from "./pages/Today";\nimport Progress from "./pages/Progress";\nimport ExerciseRepository from "./pages/ExerciseRepository";\nimport CampChat from "./pages/CampChat";\nimport Messages from "./pages/Messages";\nimport CampLeaderboard from "./pages/CampLeaderboard";\nimport Chrono from "./pages/Chrono";\n\nfunction Private({ children }: { children: ReactNode }) {\n  const { user, loading } = useAuth();\n  if (loading) return <div className="min-h-screen flex items-center justify-center text-muted">Chargement...</div>;\n  if (!user) return <Navigate to="/connexion" replace />;\n  return <Layout>{children}</Layout>;\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path="/connexion" element={<Login />} />\n      <Route path="/inscription" element={<Register />} />\n\n      <Route path="/aujourdhui" element={<Private><Today /></Private>} />\n      <Route path="/profil" element={<Private><Profile /></Private>} />\n      <Route path="/camps" element={<Private><Dashboard /></Private>} />\n      <Route path="/camps/creer" element={<Private><CreateCamp /></Private>} />\n      <Route path="/camps/rejoindre" element={<Private><JoinCamp /></Private>} />\n      <Route path="/camps/:id" element={<Private><CampDetail /></Private>} />\n      <Route path="/camps/:id/progression/:exerciseId" element={<Private><Progress /></Private>} />\n      <Route path="/exercices" element={<Private><ExerciseRepository /></Private>} />\n      <Route path="/camps/:id/discussion" element={<Private><CampChat /></Private>} />\n      <Route path="/camps/:id/classement" element={<Private><CampLeaderboard /></Private>} />\n      <Route path="/chrono" element={<Private><Chrono /></Private>} />\n      <Route path="/messages" element={<Private><Messages /></Private>} />\n\n      <Route path="*" element={<Navigate to="/aujourdhui" replace />} />\n    </Routes>\n  );\n}\n'

BINARY_FILES_B64 = {}
BINARY_FILES_B64['frontend/public/logo-full.png'] = ''
BINARY_FILES_B64['frontend/public/logo-mark.png'] = ''
BINARY_FILES_B64['frontend/public/icon-192.png'] = ''
BINARY_FILES_B64['frontend/public/icon-512.png'] = ''
BINARY_FILES_B64['frontend/public/favicon-32.png'] = ''
BINARY_FILES_B64['frontend/public/favicon-64.png'] = ''

for rel_path, content in TEXT_FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

for rel_path, b64content in BINARY_FILES_B64.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64content))
    print('OK ->', rel_path)

